// Interface
public interface IReportGenerator { Task<byte[]> Generate(); }

// Implementations
public class PdfReportGenerator : IReportGenerator
{
    public Task<byte[]> Generate() => Task.FromResult(new byte[] { 1, 2, 3 });
}

public class ExcelReportGenerator : IReportGenerator
{
    public Task<byte[]> Generate() => Task.FromResult(new byte[] { 4, 5, 6 });
}

// Factory
public interface IReportGeneratorFactory
{
    IReportGenerator Create(string format);
}

public class ReportGeneratorFactory : IReportGeneratorFactory
{
    private readonly IServiceProvider _provider;
    public ReportGeneratorFactory(IServiceProvider provider) => _provider = provider;

    public IReportGenerator Create(string format) => format.ToLower() switch
    {
        "pdf" => _provider.GetRequiredService<PdfReportGenerator>(),
        "excel" => _provider.GetRequiredService<ExcelReportGenerator>(),
        _ => throw new NotSupportedException($"Format {format} not supported")
    };
}

// Register
builder.Services.AddScoped<PdfReportGenerator>();
builder.Services.AddScoped<ExcelReportGenerator>();
builder.Services.AddScoped<IReportGeneratorFactory, ReportGeneratorFactory>();
